def chain_follower(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = sorted(chain_dict.items())

    current = chain_dict[0]
    result = []

    while current:
        result.append(', '.join(current))
        next_item = current.pop()
        if next_item not in chain_dict:
            break
        current.append(next_item)

    return ' '.join(result)
